    --font-weight-semibold: 600;
    --font-weight-bold:     700;

    --line-height-12: 12px;
    --line-height-14: 14px;
    --line-height-16: 16px;
    --line-height-18: 18px;
    --line-height-20: 20px;
    --line-height-24: 24px;
    --line-height-26: 26px;
    --line-height-30: 30px;
    --line-height-32: 32px;
    --line-height-36: 36px;
    --line-height-48: 48px;
    --line-height-60: 60px;
    --line-height-64: 64px;
