.py-16 { padding-top: 64px; padding-bottom: 64px; }
.pl-\[var\(--spacing-lg\)\] { padding-left: var(--spacing-lg); }
.mt-2 { margin-top: 8px; }
.mb-3 { margin-bottom: 12px; }
.-top-0\.5 { top: -2px; }
.-right-0\.5 { right: -2px; }
.left-1\/2 { left: 50%; }
.top-1\/2 { top: 50%; }
.-translate-y-1\/2 { transform: translateY(-50%); }
.rotate-180 { transform: rotate(180deg); }

.gap-0 { gap: 0; }
.gap-2 { gap: 8px; }
.gap-4 { gap: 16px; }
.grid-cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.space-y-2 > * + * { margin-top: 8px; }

.transition-all,
.transition-colors,
.transition-opacity,
.transition-transform {
  transition-duration: 150ms;
  transition-timing-function: ease;
}
.duration-150 { transition-duration: 150ms; }
.duration-200 { transition-duration: 200ms; }
.opacity-40 { opacity: 0.4; }

.line-clamp-2 {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* ============================================
   页面转场动画
   ============================================ */

@keyframes slide-in-right {
  from { transform: translateX(100%); }
  to   { transform: translateX(0); }
}
@keyframes slide-out-right {
  from { transform: translateX(0); }
  to   { transform: translateX(100%); }
}
@keyframes fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes slide-up {
  from { transform: translateY(100%); }
  to   { transform: translateY(0); }
}
@keyframes page-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.animate-slide-in-right { animation: slide-in-right 300ms ease-out forwards; }
.animate-slide-out-right { animation: slide-out-right 300ms ease-in forwards; }
.fade-in { animation: fade-in 300ms ease-out forwards; }
.animate-slide-up { animation: slide-up 300ms ease-out forwards; }
.animate-page-in { animation: page-in 150ms ease-out; }

.tf-cg-bottom-bar {
  position: absolute;
  left: 0;
  top: 1024px;
  width: 360px;
  height: 64px;
  background-color: var(--color-bg-card);
  border-top: 1px solid var(--color-border-subtle);
  display: flex;
  align-items: center;
  padding: 0 16px;
  box-sizing: border-box;
  box-shadow: 0 -2px 8px rgba(0,0,0,0.04);
}
.tf-cg-action-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 48px;
  gap: 2px;
  color: var(--color-text-secondary);
  cursor: pointer;
}
.tf-cg-action-item svg {
  width: 22px;
  height: 22px;
}
.tf-cg-action-item span {
  font-size: var(--font-caption-10);
  line-height: var(--line-height-12);
}
.tf-cg-primary-btn {
  flex: 1;
  margin-left: 16px;
  height: 40px;
  background-color: var(--color-primary);
  color: var(--color-text-white);
  border: none;
  border-radius: var(--radius-full);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

